namespace CleanArchitecture.Blazor.Application.Features.Subsystems.EventHandlers;

public class SubsystemCreatedEventHandler : INotificationHandler<SubsystemCreatedEvent>
{
    private readonly ILogger<SubsystemCreatedEventHandler> _logger;

    public SubsystemCreatedEventHandler(
        ILogger<SubsystemCreatedEventHandler> logger
    )
    {
        _logger = logger;
    }

    public Task Handle(SubsystemCreatedEvent notification, CancellationToken cancellationToken)
    {
        _logger.LogInformation("Subsystem created: {SubsystemName} (ID: {SubsystemId}) under System ID: {SystemId} by {CreatedBy} at {CreatedOn}", 
            notification.Item.Name, 
            notification.Item.Id,
            notification.Item.SystemId,
            notification.Item.CreatedBy, 
            notification.Item.Created);
        
        return Task.CompletedTask;
    }
}